children.text:
@font-face {
    font-family: 'Liberation Sans';
    src: url('../font/LiberationSans-Regular.ttf') format('truetype');
    font-weight: normal;
    font-style: normal;
}

body {
    font-family: 'Liberation Sans', Arial, sans-serif;
    font-size: 16px;
    line-height: 1.5;
    margin: 20px;
    background-color: white;
    color: black;
}

.narrow-container {
    width: 200px;
    padding: 15px;
    border: 2px solid #333;
    margin-bottom: 20px;
    word-wrap: break-word;
}

.medium-container {
    width: 350px;
    padding: 15px;
    border: 2px dashed #666;
    margin-bottom: 20px;
}

.long-words {
    background-color: #f0f0f0;
    padding: 10px;
    margin: 5px 0;
}
